-- 202611171800 · Sprint 3 · T7a · EL TOPE POR SEGUNDO TERMINADO · CC2 · 🟢 CC6 al diseño (REVISION-CC6-a-CC2-LENOVO-t7-tope-por-segundo) · US$ 0
-- La plantilla viva de video_mesa escribe sus topes como DATO POR SEGUNDO, con las cifras que REPRODUCEN HOY a 15 s:
--   paso `video` = 0 + 1,0/s × limites.video.segundos_max (15) = 15 · encargo = 43 + 1,0/s × 15 = 58 · `limites.video.tope_por_video_usd` sale del dato (lo calcula la carga).
-- Cargada (`aplicarTopesPorDuracion`, al leer la plantilla) da EXACTAMENTE lo de hoy (VIDEO_MESA_ENCENDIDA). La columna `tope_encargo_usd` queda en 58 = lo calculado.
-- ORDEN: el código que entiende el dato por segundo se publica ANTES de aplicar esto (el código viejo leería el video en 0 y el encargo en 43).
-- «Antes» = la fila viva leída el 17-nov 11:1xZ. Se niega con encargos vivos y si el dato no es el esperado. Reversa: reversas/202611171800_oficina_video_tope_por_segundo_REVERSA.sql
BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.oficina_encargos WHERE estado IN ('abierto', 'en_paso')) THEN
    RAISE EXCEPTION '202611171800: hay encargos de la oficina vivos; esperar a que cierren';
  END IF;
  IF (SELECT pasos FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $pasos_antes$[{"tipo":"codigo","clave":"abrir","quien":"sala","entrada":[],"funcion":"abrir_video","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"encargo"},{"tipo":"codigo","clave":"mesa","quien":"sala","entrada":["encargo"],"funcion":"mesa","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"mesa"},{"tipo":"codigo","clave":"imagenes_clave","quien":"sala","entrada":["guion","encargo"],"funcion":"imagenes_clave","tope_usd":3,"condicion":{"tipo":"siempre"},"salida_artefacto":"imagenes_clave"},{"tipo":"codigo","clave":"borrador_video","quien":"sala","entrada":["imagenes_clave"],"funcion":"borrador_video","tope_usd":10,"condicion":{"tipo":"siempre"},"salida_artefacto":"borrador_video"},{"tipo":"codigo","clave":"aprobar_propuestas","quien":"sala","entrada":["mesa"],"funcion":"aprobar_propuestas","tope_usd":0,"vuelve_a":{"si":{"tipo":"si_artefacto","campo":"vuelve_a_la_mesa","igual":true,"artefacto":"aprobacion_propuestas"},"max":2,"paso":"mesa"},"condicion":{"tipo":"siempre"},"salida_artefacto":"aprobacion_propuestas"},{"tipo":"codigo","clave":"imagenes_clave_final","quien":"sala","entrada":["guion","encargo"],"funcion":"imagenes_clave","tope_usd":3,"condicion":{"tipo":"siempre"},"salida_artefacto":"imagenes_clave_final"},{"tipo":"agente","clave":"revisar_imagenes_clave","quien":"marketing_video_optimization_specialist","salida":{"esquema":"revision_imagenes_clave.v1","reintento_formato":1},"entrada":["imagenes_clave_final","guion"],"tope_usd":0.5,"vuelve_a":{"si":{"tipo":"si_artefacto","campo":"vuelve_a_la_mesa","igual":true,"artefacto":"revision_imagenes_clave"},"max":1,"paso":"mesa"},"condicion":{"tipo":"si_artefacto","campo":"hay_imagenes","igual":true,"artefacto":"imagenes_clave_final"},"salida_artefacto":"revision_imagenes_clave"},{"tipo":"codigo","clave":"pedido","quien":"sala","entrada":["guion","copy_video"],"funcion":"pedido_de_video