e"},"salida_artefacto":"cierre"}]$pasos_antes$::jsonb THEN
    RAISE EXCEPTION '202611171800: los pasos de video_mesa no son los esperados; no se pisan';
  END IF;
  IF (SELECT limites FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM $lim_antes${"mesa":true,"video":{"borrador":{"resolucion":"480p"},"propuestas":3,"resolucion":"720p","segundos_max":15,"segundos_min":8,"plano_por_plano":true,"tope_por_video_usd":15},"margen":50,"max_rondas":2,"plataforma":"instagram-reel","reuso_dias":14,"hashtags_max":30,"imagen_clave":{"final":{"size":"1024x1536","quality":"max"},"borrador":{"size":"1024x1536","quality":"low"}},"pie_de_foto_max":2200,"tope_encargo_usd":58,"formato_por_omision":"9:16","limites_verificados":false,"reserva_por_pieza_usd":30,"imagenes_generadas_max":0}$lim_antes$::jsonb THEN
    RAISE EXCEPTION '202611171800: los límites de video_mesa no son los esperados; no se pisan';
  END IF;
  IF (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 58::numeric THEN
    RAISE EXCEPTION '202611171800: el tope del encargo de video_mesa no es el esperado; no se pisa';
  END IF;
END $$;

UPDATE public.oficina_tipos_de_grupo SET pasos = $pasos$[{"tipo":"codigo","clave":"abrir","quien":"sala","entrada":[],"funcion":"abrir_video","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"encargo"},{"tipo":"codigo","clave":"mesa","quien":"sala","entrada":["encargo"],"funcion":"mesa","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"mesa"},{"tipo":"codigo","clave":"imagenes_clave","quien":"sala","entrada":["guion","encargo"],"funcion":"imagenes_clave","tope_usd":3,"condicion":{"tipo":"siempre"},"salida_artefacto":"imagenes_clave"},{"tipo":"codigo","clave":"borrador_video","quien":"sala","entrada":["imagenes_clave"],"funcion":"borrador_video","tope_usd":10,"condicion":{"tipo":"siempre"},"salida_artefacto":"borrador_video"},{"tipo":"codigo","clave":"aprobar_propuestas","quien":"sala","entrada":["mesa"],"funcion":"aprobar_propuestas","tope_usd":0,"vuelve_a":{"si":{"tipo":"si_artefacto","campo":"vuelve_a_la_mesa","igual":true,"artefacto":"aprobacion_propuestas"},"max":2,"paso":"mesa"},"condicion":{"tipo":"siempre"},"salida_artefacto":"aprobacion_propuestas"},{"tipo":"codigo","clave":"imagenes_clave_final","quien":"sala","entrada":["guion","encargo"],"funcion":"imagenes_clave","tope_usd":3,"condicion":{"tipo":"siempre"},"salida_artefacto":"imagenes_clave_final"},{"tipo":"agente","clave":"revisar_imagenes_clave","quien":"marketing_video_optimization_specialist","salida":{"esquema":"revision_imagenes_clave.v1","reintento_formato":1},"entrada":["imagenes_clave_final","guion"],"tope_usd":0.5,"vuelve_a":{"si":{"tipo":"si_artefacto","campo":"vuelve_a_la_mesa","igual":true,"artefacto":"revision_imagenes_clave"},"max":1,"paso":"mesa"},"condicion":{"tipo":"si_artefacto","campo":"hay_imagenes","igual":true,"artefacto":"imagenes_clave_final"},"salida_artefacto":"revision_imagenes_clave"},{"tipo":"codigo","clave":"pedido","quien":"sala","entrada":["guion","copy_video"],"funcion":"pedido_de_video","tope_usd":0,"vuelve_a":{"si":{"tipo":"si_artefacto","campo":"vuelve_a_la_mesa","igual":true,"artefacto":"pedido_video"},"max":1,"paso":"mesa"},"condicion":{"tipo":"siempre"},"salida_artefacto":"pedido_video"},{"tipo":"codigo","clave":"video","quien":"sala","entrada":["pedido_video"],"funcion":"video","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"video","tope_usd_por_segundo":1},{"tipo":"codigo","clave":"cuadros_video","quien":"sala","entrada":["video","guion"],"funcion":"cuadros_video","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"cuadros_video"},{"tipo":"agente","clave":"mirar_video","quien":"marketing_video_optimization_specialist","salida":{"esquema":"mirada_video.v1","reintento_formato":1},"entrada":["cuadros_video","guion"],"tope_usd":0.5,"vuelve_a":{"si":{"tipo":"si_artefacto","campo":"vuelve_a_la_mesa","igual":true,"artefacto":"mirada_video"},"max":1,"paso":"mesa"},"condicion":{"tipo":"si_artefacto","campo":"hay_cuadros","igual":true,"artefacto":"cuadros_video"},"salida_artefacto":"mirada_video"},{"tipo":"codigo","clave":"chequeos","quien":"sala","entrada":["video","copy_video","pedido_video"],"funcion":"chequeos_video","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"chequeos"},{"tipo":"jefatura","clave":"jefatura","quien":"jefatura","entrada":["guion","copy_video","video","chequeos"],"tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"respuesta_imagen"},{"tipo":"codigo","clave":"chequeos_2","quien":"sala","entrada":["video","copy_video","pedido_video"],"funcion":"chequeos_video","tope_usd":0,"condicion":{"tipo":"si_cambio","artefacto":"copy_video"},"salida_artefacto":"chequeos"},{"tipo":"codigo","clave":"entrega","quien":"sala","entrada":["copy_video","video","chequeos","guion"],"funcion":"empaquetar_entrega_video","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"entrega"},{"tipo":"codigo","clave":"cierre","quien":"sala","entrada":["entrega"],"funcion":"cierre","tope_usd":0,"condicion":{"tipo":"siempre"},"salida_artefacto":"cierre"}]$pasos$::jsonb,
  limites = $lim${"mesa":true,"video":{"borrador":{"resolucion":"480p"},"propuestas":3,"resolucion":"720p","segundos_max":15,"segundos_min":8,"plano_por_plano":true},"margen":50,"max_rondas":2,"plataforma":"instagram-reel","reuso_dias":14,"hashtags_max":30,"imagen_clave":{"final":{"size":"1024x1536","quality":"max"},"borrador":{"size":"1024x1536","quality":"low"}},"pie_de_foto_max":2200,"tope_encargo_usd":43,"formato_por_omision":"9:16","limites_verificados":false,"reserva_por_pieza_usd":30,"imagenes_generadas_max":0,"tope_encargo_usd_por_segundo":1}$lim$::jsonb
  WHERE familia = 'video_mesa';

DO $$
BEGIN
  IF (SELECT (SELECT (p->>'tope_usd_por_segundo')::numeric FROM jsonb_array_elements(pasos) p WHERE p->>'clave' = 'video') FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') IS DISTINCT FROM 1::numeric
     OR (SELECT (limites->>'tope_encargo_usd')::numeric + (limites->>'tope_encargo_usd_por_segundo')::numeric * (limites->'video'->>'segundos_max')::numeric FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa')
        IS DISTINCT FROM (SELECT tope_encargo_usd FROM public.oficina_tipos_de_grupo WHERE familia = 'video_mesa') THEN
    RAISE EXCEPTION '202611171800: el dato por segundo no quedó, o no da la columna (58)';
  END IF;
END $$;

COMMIT;
